exec(open("batches/hiv_common.py").read())
# HIV 2022 part 5, pp.300-303 (Annexes 11.23 low readiness scores, 11.24 depression assessment (PHQ-9, Siswati and English) and score,
# 11.25 Karnofsky, 11.26 uses of CD4 and VL). From the page images (the Siswati text layer has lost glyphs; read from the image).
AN = "Chapter 11: Annexes"
Q = ["0", "1", "2", "3"]
SW = ["Kuncishelwa ngumdlandla/inshisekelo ekwenteni tintfo letikuchazako/letikujabulisako",
      "Kutiva uphansi emoyeni, ukhatsatekile noma ute litsemba",
      "Bulukhuni bekwehlelwa butfongo noma kuphelelwa butfongo noma kuba nebutfongo lobuningi",
      "Kutiva udziniwe noma uphelelwa ngemandla",
      "Kungakhanuki kudla (inhlitiyo imnyama) noma kudla kakhulu",
      "Kuva utisola/utenyanya noma usehluleki noma utentele phansi noma wentele phansi umndeni wakho",
      "Kuba nebulukhuni kubeka umcondvo/kulandzelela etintfweni lotentako, letinjengekufundza liphephandzaba noma kubukela mabonakudze (TV)",
      "Kuhamba kancane noma kunamula lokunakekako kulabanye bantfu. Noma kungahlaliseki kangangekutsi uhlala uphitsitela lokungetulu kwalokutayelekile",
      "Kuba nemicabango yekutsi kuncono kufa, noma ucabange kutilimata."]
EN = ["1. Little interest or pleasure in doing things", "2. Feeling down, depressed, or hopeless", "3. Trouble falling or staying asleep, or sleeping too much",
      "4. Feeling tired or having little energy", "5. Poor appetite or overeating", "6. Feeling bad about yourself or that you are a failure or have let yourself or your family down",
      "7. Trouble concentrating (on things linked with your usual activities)", "8. Moving or speaking so slowly that other people could have noticed, or, on the contrary, being fidgety, restless, or moving around a lot more than usual",
      "9. Thoughts that you would be better off dead or hurting yourself in some way"]
ITEMS = [
 T("tbl-11.23-low-readiness-scores", 300, AN + " > 11.23 Guidance on patients with low scores on ART readiness assessment", "Annex 11.23 Guidance on patients with low scores on ART readiness assessment", ["0804", "0805"],
   [r("Assessment", "Remedial action")],
   [r("From I- XVI", "Additional counselling and patient education on identified knowledge gaps/ low scores to improve patient literacy and support by a nurse/ doctor or social worker<br/>Involve treatment/ Peer supporter for counselling for additional support<br/>Link to support group and community support structures"),
    r("V- VI", "Appoint re- counselling session with Treatment/ supporter<br/>- Link to support group and other community support structures"),
    r("VIII", "- Counsel for assisted disclosure with EC, Peer supporter, Nurse or social worker"),
    r("IX", "- Identify treatment supporter<br/>- Emphasize setting reminders"),
    r("X", "- Refer to nurse/ doctor for assessment, management and decision to initiate or delay ART"),
    r("XI", "- Assess the barrier<br/>- Counsel on possible remedial actions<br/>- Discuss, Agree and revise the treatment plan to address barriers<br/>- Identify/ engage treatment supporter/ Peer supporter<br/>- Assist and Arrange for referral to additional support structures (Nurse, social worker, Psychiatric nurse, OVC-DREAMS Linkage Case Assistants)"),
    r("XII", "If the Client is not ready for ART initiation<br/>- Review potential barriers to ART initiation<br/>- Additional counselling and patient education on identified knowledge gaps/ low scores to improve patient literacy and support by a nurse/ doctor or social worker<br/>- Assist and Arrange for referral to additional support structures (Nurse, social worker, Psychiatric nurse, OVC-DREAMS Linkage Case Assistants)<br/>- Engage Treatment supporter<br/>- Reappoint patient for follow-up +/- ART initiation within 2 weeks."),
    r("XIII", "- Review potential barriers to ART initiation<br/>- Additional counselling and patient education on identified knowledge gaps/ low scores to improve patient literacy and support by a nurse/ doctor or social worker<br/>- Assist and Arrange for referral to additional support structures (Nurse, social worker, Psychiatric nurse, OVC-DREAMS Linkage Case Assistants)<br/>- Engage Treatment supporter"),
    r("XVI", "- Additional counselling and patient education on identified knowledge gaps/ low scores to improve patient literacy and support by a nurse/ doctor or social worker<br/>- Involve treatment/ Peer supporter for counselling for additional support<br/>- Link to support group and community support structures")],
   source_flags=["Annex 11.23 refers to assessment sections I-XVI, but the readiness form in Annex 11.22 has no numbered sections, and no scoring is given, so the 'low scores' cannot be mapped."]),
 T("tbl-11.24-phq9-siswati", 301, AN + " > 11.24 Depression Assessment > Siswati", "Annex 11.24 Depression Assessment (Siswati PHQ-9)", ["0806", "0807"],
   [[C("Sebentisa nalu luphawu √ kuphendvula", cs=5)], r("", "Akukake kwenteka", "Emalanga lambalwa", "Lokungetulu kweliviki (7 days)", "Cishe onkhe emalanga")],
   [r(q, *Q) for q in SW] + [[C("SEKUKONKHE:"), C("", cs=4)]],
   footnotes=["Below the table: Sisebenti setemphilo; kutfola inchazelo ngemphumela buka luhla lwetinchazelo ngemuva kuhlatiya umphumela. Nangabe ubeke luphawu kulenye yaletinkinga, kwente kwaba lukhuni kangakanani kutsi wente umsebenti, unakekele kahle likhaya noma uphilisane kahle nebantfuukabi nebulukhuni: Kube lukhunyana / Kube lukhuni kakhulu / Kube lukhuni ngalokwecile.",
              "The Siswati items are the nine PHQ-9 questions in the same order as the English version (next table)."]),
 T("tbl-11.24-phq9-english", 302, AN + " > 11.24 Depression Assessment > English", "Annex 11.24 Depression Assessment (English PHQ-9)", ["0808", "0809"],
   [[C("Over the last 2 weeks, how often have you been bothered by any of the following problems?", cs=5)], r("", "Not at all", "Several days", "More than half the days", "Nearly every day")],
   [r(q, *Q) for q in EN] + [[C("TOTAL:"), C("", cs=4)]],
   footnotes=["If you checked off any problems, how difficult have these problems made it for you to do your work, take care of things at home, or get along with other people? Not difficult at all / Somewhat difficult / Very difficult / Extremely difficult."]),
 T("tbl-11.24-phq9-score", 302, AN + " > 11.24 Depression Assessment > Depression Assessment Score (English and Siswati)", "Depression Assessment Score (English and Siswati)", ["0810"],
   [r("Client Health Questionnaire Score (English and Siswati)", "Provisional diagnosis", "Recommendation")],
   [r("5–9", "Minimal symptoms", "Support and educate to call for support if symptoms get worse."),
    r("10–14", "Minor to mild depression or chronic depression (symptoms lasting for 2 years)", "Support and watchful waiting. Reassess in 1–2 weeks.<br/>Consider starting treatment for psychological support."),
    r("15–19", "Major depression", "Refer to social workers/psychologist/nurse. Needed for specific treatment."),
    r(">20", "Severe depression", "Major impairment, need for active treatment.")],
   source_flags=["The PHQ-9 score bands leave out 0-4 and a score of exactly 20 (5-9, 10-14, 15-19, >20), and nothing is said about a positive answer to item 9 (thoughts of death or self-harm), which needs same-day suicide risk assessment (see the 2024 Amendment Chapter 10 suicide screening)."]),
 T("tbl-11.25-karnofsky", 303, AN + " > 11.25 Karnofsky performance status", "Annex 11.25 Karnofsky performance status", ["0811"],
   [r("Status", "Response")],
   [r("100%", "Normal, no complaints, no signs of disease"), r("90%", "Capable of normal activity, minor symptoms or signs of disease"),
    r("80%", "Normal activity with some difficulty, some symptoms or signs"), r("70%", "Caring for self, not capable of normal activity or work"),
    r("60%", "Requiring some help can take care of most personal requirements"), r("50%", "Requires help often, requires frequent medical care"),
    r("40%", "Disabled, requires special care and help"), r("30%", "Severely disabled, hospital admission indicated but no risk of death"),
    r("20%", "Very ill, urgently requiring admission, requires supportive measures or treatment"), r("10%", "Moribund, rapidly progressive fatal disease processes"), r("0%", "Death")]),
 T("tbl-11.26-cd4-vl-uses", 303, AN + " > 11.26 Summary of the Uses of CD4 and Viral Load Monitoring", "Annex 11.26 Summary of the Uses of CD4 and Viral Load Monitoring", ["0812"],
   [r("Use", "CD4", "VL")],
   [r("Baseline laboratory for clients diagnosed with HIV", "X", ""), r("Disease progression for clients with HIV who have not initiated ART", "X", ""),
    r("To determine immune status at enrolment—mild, moderate or advanced immunodeficiency", "X", ""), r("To determine if LF TB-LAM testing and LF-CrAg screening should be conducted", "X", ""),
    r("To assess treatment success or failure", "", "X"), r("To assess if a client is stable or unstable on ART", "X", "X"),
    r("To assess adherence to treatment", "", "X"), r("To assess eligibility for DSD", "", "X")],
   source_flags=["Superseded in part by the 2024 Amendment: a pretreatment (baseline) VL is now done for new initiators (Amendment 5.1), whereas Annex 11.26 marks baseline laboratory testing as CD4 only."]),
]
